-- Initial schema for the CV/JD, skill-gap and adaptive interview pipeline.
-- UUIDs are generated by the application; no PostgreSQL extensions are required.

CREATE TABLE users (
    id UUID PRIMARY KEY,
    username VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(50) NOT NULL,
    phone_number VARCHAR(50),
    avatar_url VARCHAR(255),
    default_resume_id UUID,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE resumes (
    id UUID PRIMARY KEY,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    file_name VARCHAR(255) NOT NULL,
    raw_text TEXT,
    file_url VARCHAR(500),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE users ADD CONSTRAINT fk_users_default_resume
    FOREIGN KEY (default_resume_id) REFERENCES resumes(id) ON DELETE SET NULL;

CREATE TABLE job_descriptions (
    id UUID PRIMARY KEY,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    title VARCHAR(255) NOT NULL,
    raw_text TEXT,
    file_url VARCHAR(500),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE sessions (
    id VARCHAR(128) PRIMARY KEY,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    resume_id UUID REFERENCES resumes(id) ON DELETE SET NULL,
    jd_id UUID REFERENCES job_descriptions(id) ON DELETE SET NULL,
    status VARCHAR(50),
    interview_type VARCHAR(50),
    role_title VARCHAR(255),
    overall_score INTEGER,
    overall_feedback TEXT,
    user_rating INTEGER,
    user_feedback_text TEXT,
    skill_gap_json TEXT,
    gap_report_json TEXT,
    ai_interview_session_id VARCHAR(128),
    interview_report_json TEXT,
    started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ended_at TIMESTAMP
);

CREATE TABLE session_turns (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id VARCHAR(128) NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    question TEXT,
    answer TEXT,
    score INTEGER,
    strengths TEXT,
    improvements TEXT,
    suggested_answer TEXT,
    topic_tag VARCHAR(100),
    is_deep_dive BOOLEAN DEFAULT FALSE,
    hr_rating INTEGER,
    hr_feedback TEXT
);

CREATE TABLE hr_evaluations (
    id UUID PRIMARY KEY,
    session_id VARCHAR(128) NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    evaluator_name VARCHAR(255),
    rating_matching_accuracy INTEGER CHECK (rating_matching_accuracy BETWEEN 1 AND 5),
    rating_ai_rationale INTEGER CHECK (rating_ai_rationale BETWEEN 1 AND 5),
    rating_question_quality INTEGER CHECK (rating_question_quality BETWEEN 1 AND 5),
    feedback_notes TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_resumes_user_created ON resumes(user_id, created_at DESC);
CREATE INDEX idx_jds_user_created ON job_descriptions(user_id, created_at DESC);
CREATE INDEX idx_sessions_user_started ON sessions(user_id, started_at DESC);
CREATE INDEX idx_sessions_resume_id ON sessions(resume_id);
CREATE INDEX idx_sessions_jd_id ON sessions(jd_id);
CREATE INDEX idx_users_default_resume_id ON users(default_resume_id);
CREATE INDEX idx_session_turns_session_id_id ON session_turns(session_id, id);
CREATE INDEX idx_hr_eval_session_id ON hr_evaluations(session_id);
CREATE INDEX idx_hr_eval_user_id ON hr_evaluations(user_id);

